  var VN = function (items) { return P.venn('Even', 'More than 10', items); };
  LI(409, 'learn3', ['Venn and Carroll diagrams', 'How can I sort data with Venn and Carroll diagrams?',
    'A Venn diagram sorts things into circles. Things that fit both go in the overlap. Things that fit neither go outside.', VN([['4', 70, 95], ['12', 145, 95], ['15', 215, 95]]),
    [['sort', 'put into groups', '🗂️'], ['Venn diagram', 'overlapping circles', '⭕'], ['overlap', 'the middle part: both', '🔗'], ['Carroll diagram', 'a sorting table with yes and no', '▦']],
    [['Ollie sorts numbers: is it even? is it more than 10?', C(['4', '12', '15', '7'])],
      ['4 is even only. 15 is more than 10 only. 12 is both.', VN([['4', 70, 95], ['12', 145, 95], ['15', 215, 95]])],
      ['7 is neither, so it goes outside the circles.', VN([['4', 70, 95], ['12', 145, 95], ['15', 215, 95], ['7', 270, 160]])]],
    [['Where does 20 go?', ['Is 20 even? Yes.', 'Is 20 more than 10? Yes.', 'Both: the overlap.'], 'In the middle', VN([['20', 145, 95]])],
      ['Where does 8 go?', ['Is 8 even? Yes.', 'More than 10? No.'], 'In the Even circle only', VN([['8', 70, 95]])],
      ['In a Carroll diagram, where does 13 go?', ['Even? No.', 'More than 10? Yes.'], 'Not even, more than 10', P.tbl([['Even', '12', '4'], ['Not even', '13', '7']], ['', 'More than 10', 'Not more than 10'])]],
    ['If something fits both, put it in the overlap, not in one circle.', VN([['12', 145, 95]])],
    ['Where does <b>6</b> go?', VN([]), ['Even only', 'Both', 'Neither'], 'Even only', '6 is even but not more than 10.', 'Ask both questions.'],
    ['Ask both questions, then place it.', C(['one circle', 'overlap: both', 'outside: neither'])]]);

